import math
from fractions import Fraction

def hilbert_matrix(n):
    H = []
    for i in range(n):
        row = []
        for k in range(n):
            # H[i][k] = 1 / (i + k + 1)
            row.append(Fraction(1, i + k + 1))
        H.append(row)
    return H

def matrix_inverse(matrix):
    n = len(matrix)
    # Create augmented matrix [A | I]
    aug = []
    for i in range(n):
        row = []
        # Original part
        for val in matrix[i]:
            row.append(val)
        # Identity part
        for j in range(n):
            if i == j:
                row.append(Fraction(1, 1))
            else:
                row.append(Fraction(0, 1))
        aug.append(row)

    # Forward elimination with partial pivoting (not strictly needed for Hilbert but good practice)
    # We will just do Gaussian elimination assuming no zero pivots (Hilbert is non-singular)
    col = 0
    for pivot_row in range(n):
        # Find pivot (simple: pick current)
        # Swap rows if necessary
        max_val = abs(aug[pivot_row][col])
        max_idx = pivot_row
        for r in range(pivot_row + 1, n):
            if abs(aug[r][col]) > max_val:
                max_val = abs(aug[r][col])
                max_idx = r

        # Swap
        if max_idx != pivot_row:
            aug[pivot_row], aug[max_idx] = aug[max_idx], aug[pivot_row]

        pivot = aug[pivot_row][col]
        # Normalize pivot row
        for c in range(2 * n):
            aug[pivot_row][c] /= pivot

        # Eliminate other rows
        for r in range(n):
            if r != pivot_row:
                factor = aug[r][col]
                for c in range(2 * n):
                    aug[r][c] -= factor * aug[pivot_row][c]
        col += 1

    # Extract inverse
    inv = []
    for i in range(n):
        row = []
        for j in range(n):
            row.append(aug[i][n + j])
        inv.append(row)
    return inv

